add_action( 'product_cat_add_form_fields', 'perfectpixel_cat_title_add_field' );
add_action( 'product_cat_edit_form_fields', 'perfectpixel_cat_title_edit_field' );
add_action( 'created_product_cat', 'perfectpixel_cat_title_save' );
add_action( 'edited_product_cat', 'perfectpixel_cat_title_save' );
add_filter( 'woocommerce_page_title', 'perfectpixel_cat_title_output' );

function perfectpixel_cat_title_add_field() {
	wp_nonce_field( 'perfectpixel_cat_title', 'perfectpixel_cat_title_nonce' );
	echo '<div class="form-field"><label for="perfectpixel_page_title">Τίτλος σελίδας</label><input type="text" id="perfectpixel_page_title" name="perfectpixel_page_title" value=""><p>Κύριος τίτλος στη σελίδα της κατηγορίας. Κενό = το όνομα της κατηγορίας.</p></div>';
}

function perfectpixel_cat_title_edit_field( $term ) {
	wp_nonce_field( 'perfectpixel_cat_title', 'perfectpixel_cat_title_nonce' );
	$value = get_term_meta( $term->term_id, 'perfectpixel_page_title', true );
	echo '<tr class="form-field"><th scope="row"><label for="perfectpixel_page_title">Τίτλος σελίδας</label></th><td><input type="text" id="perfectpixel_page_title" name="perfectpixel_page_title" value="' . esc_attr( $value ) . '"><p class="description">Κύριος τίτλος στη σελίδα της κατηγορίας. Κενό = το όνομα της κατηγορίας.</p></td></tr>';
}

function perfectpixel_cat_title_save( $term_id ) {
	if ( ! isset( $_POST['perfectpixel_cat_title_nonce'], $_POST['perfectpixel_page_title'] ) || ! current_user_can( 'manage_product_terms' ) ) {
		return;
	}
	if ( wp_verify_nonce( sanitize_key( $_POST['perfectpixel_cat_title_nonce'] ), 'perfectpixel_cat_title' ) ) {
		update_term_meta( $term_id, 'perfectpixel_page_title', sanitize_text_field( wp_unslash( $_POST['perfectpixel_page_title'] ) ) );
	}
}

function perfectpixel_cat_title_output( $title ) {
	if ( function_exists( 'is_product_category' ) && is_product_category() ) {
		$custom = get_term_meta( get_queried_object_id(), 'perfectpixel_page_title', true );
		if ( '' !== (string) $custom ) {
			return $custom;
		}
	}
	return $title;
}
